create table if not exists public.angelcare_marketplace_quality_findings(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('FND-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,11))),assessment_id uuid not null references public.angelcare_marketplace_quality_assessments(id),criterion_id uuid references public.angelcare_marketplace_quality_assessment_criteria(id),finding_type text not null,severity text not null,description text not null,critical_flag boolean not null default false,status text not null default 'open',owner_id uuid,due_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_quality_non_conformities(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('NC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,11))),assessment_id uuid references public.angelcare_marketplace_quality_assessments(id),complaint_id uuid,territory_id uuid,tenant_id uuid,severity text not null,finding text not null,status text not null default 'identified',owner_id uuid,due_at timestamptz,critical_flag boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_quality_corrective_actions(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('CAPA-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),source_type text not null,source_id uuid not null,territory_id uuid,tenant_id uuid,severity text not null,finding text not null,root_cause text,containment_action text,corrective_action text,preventive_action text,owner_id uuid,due_at timestamptz,status text not null default 'identified' check(status in('identified','triaged','containment_required','containment_active','root_cause_analysis','action_planned','action_in_progress','evidence_submitted','effectiveness_review','effective','ineffective','reopened','closed','cancelled')),overdue_flag boolean not null default false,effectiveness_result text,residual_risk text,reviewer_id uuid,closed_by uuid,closed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_quality_effectiveness_reviews(id uuid primary key default gen_random_uuid(),action_id uuid not null references public.angelcare_marketplace_quality_corrective_actions(id),reviewer_id uuid not null,decision text not null check(decision in('effective','ineffective','reopen')),evidence jsonb not null default '{}',residual_risk text,comments text,reviewed_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_complaints(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('CMP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,11))),complainant_type text not null,protected_identity jsonb not null default '{}',territory_id uuid,tenant_id uuid,organization_id uuid,related_object_type text,related_object_id uuid,category text not null,severity text not null default 'moderate',received_channel text not null,received_at timestamptz not null default now(),consent_classification text,privacy_classification text not null default 'restricted',summary text not null,protected_narrative text,evidence_ids uuid[] not null default '{}',owner_id uuid,service_deadline timestamptz,status text not null default 'received' check(status in('received','acknowledged','triaged','assigned','under_investigation','information_required','response_prepared','resolution_proposed','resolved','appealed','reopened','closed','withdrawn')),open_flag boolean generated always as (status not in('resolved','closed','withdrawn')) stored,next_action text,created_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_complaint_communications(id uuid primary key default gen_random_uuid(),complaint_id uuid not null references public.angelcare_marketplace_complaints(id) on delete cascade,channel text not null,direction text not null,recipient_type text,content_summary text not null,sensitive_content text,actor_id uuid,occurred_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_complaint_investigations(id uuid primary key default gen_random_uuid(),complaint_id uuid not null references public.angelcare_marketplace_complaints(id),investigator_id uuid not null,scope text not null,findings jsonb not null default '[]',evidence_ids uuid[] not null default '{}',status text not null default 'assigned',started_at timestamptz,completed_at timestamptz,reviewer_id uuid,reviewed_at timestamptz,created_at timestamptz not null default now());
