create table if not exists public.angelcare_marketplace_sensitive_content_reviews(id uuid primary key default gen_random_uuid(),content_type text not null,content_id uuid not null,territory_id uuid,tenant_id uuid,source_locale text not null default 'fr' check(source_locale='fr'),source_version int not null,translation_status text not null default 'incomplete',evidence_status text not null default 'missing',domain_owner_status text not null default 'pending',compliance_status text not null default 'pending',publication_status text not null default 'blocked',blocking_reasons text[] not null default '{}',domain_owner_id uuid,compliance_reviewer_id uuid,approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(content_type,content_id,territory_id,source_version));
