create or replace function public.angelcare_marketplace_transition_sop(p_sop_id uuid,p_next_status text,p_reason text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_trust_sops;begin update public.angelcare_marketplace_trust_sops set status=p_next_status,next_action=case when p_next_status='effective' then 'Planifier la revue et les acknowledgements.' when p_next_status in('suspended','expired') then 'Retirer des sélections opérationnelles.' else next_action end,effective_at=case when p_next_status='effective' then coalesce(effective_at,now()) else effective_at end,updated_by=p_actor_id,updated_at=now() where id=p_sop_id returning * into r;if r.id is null then raise exception 'SOP introuvable';end if;return to_jsonb(r);end$$;
create or replace function public.angelcare_marketplace_transition_quality_assessment(p_assessment_id uuid,p_next_status text,p_reason text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_quality_assessments;begin update public.angelcare_marketplace_quality_assessments set status=p_next_status,approved_by=case when p_next_status='approved' then p_actor_id else approved_by end,approved_at=case when p_next_status='approved' then now() else approved_at end,updated_at=now() where id=p_assessment_id returning * into r;if r.id is null then raise exception 'Assessment introuvable';end if;return to_jsonb(r);end$$;
create or replace function public.angelcare_marketplace_transition_complaint(p_complaint_id uuid,p_next_status text,p_reason text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_complaints;begin update public.angelcare_marketplace_complaints set status=p_next_status,next_action=case when p_next_status='triaged' then 'Assigner un investigator et confirmer le SLA.' when p_next_status='resolved' then 'Communiquer la résolution et ouvrir la période d’appel.' when p_next_status='closed' then null else next_action end,updated_at=now() where id=p_complaint_id returning * into r;if r.id is null then raise exception 'Plainte introuvable';end if;return to_jsonb(r);end$$;
create or replace function public.angelcare_marketplace_transition_capa(p_action_id uuid,p_next_status text,p_reason text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_quality_corrective_actions;begin if p_next_status='closed' and not exists(select 1 from public.angelcare_marketplace_quality_effectiveness_reviews where action_id=p_action_id and decision='effective') then raise exception 'Effectiveness review required before closure';end if;update public.angelcare_marketplace_quality_corrective_actions set status=p_next_status,closed_by=case when p_next_status='closed' then p_actor_id else closed_by end,closed_at=case when p_next_status='closed' then now() else closed_at end,updated_at=now() where id=p_action_id returning * into r;if r.id is null then raise exception 'CAPA introuvable';end if;return to_jsonb(r);end$$;
create or replace function public.angelcare_marketplace_public_trust_verification(p_reference text) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_trust_badge_issuances;d public.angelcare_marketplace_trust_badge_definitions;begin select * into r from public.angelcare_marketplace_trust_badge_issuances where verification_reference=p_reference and status in('active','expiring');if r.id is null then return null;end if;select * into d from public.angelcare_marketplace_trust_badge_definitions where id=r.badge_definition_id;return jsonb_build_object('reference',r.verification_reference,'objectType',r.object_type,'title',d.name_fr,'status',r.status,'issuedAt',r.issued_at,'validUntil',r.valid_until,'issuer','ANGELCARE Trust Authority','publicClaims',to_jsonb(r.public_claims));end$$;

create or replace function public.angelcare_marketplace_recalculate_quality_assessment(p_assessment_id uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_quality_assessments;available numeric:=0;earned numeric:=0;critical_count int:=0;begin select coalesce(sum(c.weight) filter(where x.outcome not in('not_applicable','not_observed')),0),coalesce(sum(case when x.outcome='compliant' then c.weight when x.outcome='partially_compliant' then c.weight*.5 else 0 end),0),coalesce(count(*) filter(where x.outcome='critical_failure'),0) into available,earned,critical_count from public.angelcare_marketplace_quality_assessment_responses x join public.angelcare_marketplace_quality_assessment_criteria c on c.id=x.criterion_id where x.assessment_id=p_assessment_id;update public.angelcare_marketplace_quality_assessments set score=case when available>0 then round(earned/available*100,2) else 0 end,critical_failures=critical_count,risk_level=case when critical_count>0 then 'critical' when available=0 then 'unknown' when earned/available<.6 then 'high' when earned/available<.8 then 'moderate' else 'controlled' end,updated_at=now() where id=p_assessment_id returning * into r;if r.id is null then raise exception 'Quality Check 360 introuvable';end if;return to_jsonb(r);end$$;
create or replace function public.angelcare_marketplace_approve_sensitive_content(p_review_id uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_sensitive_content_reviews;begin select * into r from public.angelcare_marketplace_sensitive_content_reviews where id=p_review_id for update;if r.id is null then raise exception 'Sensitive review introuvable';end if;if r.source_locale<>'fr' then raise exception 'French canonical source required';end if;if r.translation_status<>'approved' then raise exception 'Approved translations required';end if;if r.evidence_status<>'current' then raise exception 'Approved evidence required';end if;if r.domain_owner_status<>'approved' then raise exception 'Domain owner approval required';end if;if cardinality(r.blocking_reasons)>0 then raise exception 'Blocking reasons remain';end if;update public.angelcare_marketplace_sensitive_content_reviews set compliance_status='approved',publication_status='approved',compliance_reviewer_id=p_actor_id,approved_at=now(),updated_at=now() where id=p_review_id returning * into r;return to_jsonb(r);end$$;
