insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and (p.permission_key like 'marketplace.trust.%' or p.permission_key like 'marketplace.quality.%' or p.permission_key like 'marketplace.complaints.%' or p.permission_key like 'marketplace.sensitive_content.%' or p.permission_key like 'marketplace.compliance.%') on conflict do nothing;
